import{H as e,St as t,at as n,it as r,ot as i,st as a,tt as o,vt as s}from"./chunks/framework.dmHZ7NHG.js";var c=JSON.parse(`{"title":"Books","description":"Audit and decode public-domain books through public APIs — a recomputable provenance fingerprint, a structural decode, and an honesty-gate pass. Provenance for translations and for the books you write. Public-domain, free for the public interest.","frontmatter":{"title":"Books","description":"Audit and decode public-domain books through public APIs — a recomputable provenance fingerprint, a structural decode, and an honesty-gate pass. Provenance for translations and for the books you write. Public-domain, free for the public interest."},"headers":[],"relativePath":"docs/books.md","filePath":"docs/books.md"}`),l={name:`docs/books.md`},u={id:`books`,tabindex:`-1`};function d(e,c,l,d,f,p){let m=t(`Badge`),h=t(`BookReflect`);return s(),r(`div`,null,[o(`h1`,u,[c[0]||=i(`Books `,-1),a(m,{type:`tip`,text:`public-domain`}),c[1]||=i(),c[2]||=o(`a`,{class:`header-anchor`,href:`#books`,"aria-label":`Permalink to “Books”`},`​`,-1)]),c[3]||=n(`<blockquote><p>Provenance for what is read, translated, and written — recomputable by anyone.</p></blockquote><p>uuidna audits and structurally <strong>decodes</strong> public-domain books. &quot;Decode&quot; here is <strong>provenance and structure</strong> — never decryption (a book is not encrypted) and never hidden meaning. Free for the public interest.</p><h2 id="what-an-audit-is" tabindex="-1">What an audit is <a class="header-anchor" href="#what-an-audit-is" aria-label="Permalink to “What an audit is”">​</a></h2><p>Every audit — of a fetched book, of pasted text, of a translation — has three parts, each recomputable:</p><ol><li><strong>Provenance fingerprint.</strong> The content-address of the exact text — proof you hold <em>that</em> edition, byte for byte, recomputable by anyone. Plus a <strong>chapter merkle root</strong>, so any single chapter can be proven to belong to the whole.</li><li><strong>Structural decode.</strong> Chapters, characters, words, lines; the ℤ/9 <strong>digital-root gravity</strong> of the length (a recomputable checksum digit — <em>not</em> a meaning); and a reversible-imprint round-trip. Structure, not interpretation.</li><li><strong>Honesty-gate pass.</strong> The prose is run through the same gate that audits uuidna&#39;s own claims. Honest caveat: the gate is tuned to uuidna&#39;s overclaim vocabulary, so on ordinary literature it says nothing about the work — and it <strong>shows its hit</strong>, so a spurious match (say, &quot;next generation&quot; in Austen) is visible as the false positive it is.</li></ol><h2 id="audit-a-public-book" tabindex="-1">Audit a public book <a class="header-anchor" href="#audit-a-public-book" aria-label="Permalink to “Audit a public book”">​</a></h2><p><code>uuidna_audit_book</code> fetches a public-domain text from <strong>Project Gutenberg</strong> (via the public Gutendex API, no key — the one tool that reaches the network) and audits it. For example, Gutenberg <strong>#1342</strong>, <em>Pride and Prejudice</em>:</p><table tabindex="0"><thead><tr><th>field</th><th>value</th></tr></thead><tbody><tr><td>title</td><td>Pride and Prejudice — Jane Austen</td></tr><tr><td>address (exact-copy fingerprint)</td><td><code>2070847f-4772-8171-b6db-b7d60d95669c</code></td></tr><tr><td>chapters · chars · words</td><td>62 · 763,082 · 130,415</td></tr><tr><td>gravity (ℤ/9 checksum)</td><td>8</td></tr><tr><td>source</td><td><code>gutenberg.org/ebooks/1342.txt.utf-8</code></td></tr></tbody></table><p>The fetched text is <strong>data</strong> — content-addressed and counted, never executed. Any instruction-shaped prose inside a book is content, not a command. To audit text you already hold, use <code>uuidna_audit_text</code>.</p><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to “Translations”">​</a></h2><p><code>uuidna_audit_translation</code> audits a translation as a <strong>source ↔ translation pair</strong>: each side keeps its own exact-copy fingerprint, and a <strong>directional receipt</strong> (<code>source → translation</code>) binds them. Re-address after each revision and the change is visible in the receipt.</p><p>Honest scope: this proves the <strong>pairing</strong> and each text&#39;s <strong>integrity</strong> — never that the translation is accurate or faithful. Semantic fidelity is human judgement; provenance is what recomputes.</p><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to “Writing”">​</a></h2><p>A book you write is audited the same way: content-address each chapter, fold them to the <strong>chapter root</strong>. Every revision re-addresses, so a change is never silent — authorship and integrity are recomputable, edit by edit. uuidna proves the text is exactly what it is; it does not judge whether the writing is good. Integrity, not truth.</p><p>Write below and the audit <strong>reflects back live, in your browser</strong> — the same offline <code>auditText</code> the MCP tool runs, recomputing on every keystroke. Nothing is sent, stored, or tracked:</p>`,15),a(h),c[4]||=n(`<h2 id="honest-scope" tabindex="-1">Honest scope <a class="header-anchor" href="#honest-scope" aria-label="Permalink to “Honest scope”">​</a></h2><ul><li><strong>Provenance + structure</strong>, never decryption or hidden meaning or numerology.</li><li>The <strong>gravity</strong> digit is a mod-9 checksum of the length — a fingerprint digit, not a message.</li><li>uuidna proves <strong>exact-copy, belonging, and pairing</strong> — not literary merit, and not translation accuracy.</li><li>Public-domain works only; <strong>free for the public interest</strong>. See the <a href="/mcp">MCP tools</a> and the <a href="/captain/config">Contract</a>.</li></ul>`,2)])}var f=e(l,[[`render`,d]]);export{c as __pageData,f as default};